import{_ as t,o as e,c as u,ag as q}from"./chunks/framework.CAXxHpAX.js";const k=JSON.parse('{"title":"心经金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-心经.md","filePath":"40-原话金句/quote-心经.md","lastUpdated":1778155802000}'),r={name:"40-原话金句/quote-心经.md"};function a(l,o,c,n,s,b){return e(),u("div",null,[...o[0]||(o[0]=[q('<h1 id="心经金句" tabindex="-1">心经金句 <a class="header-anchor" href="#心经金句" aria-label="Permalink to &quot;心经金句&quot;">​</a></h1><blockquote><p>了空居士讲解《心经》精彩原话集</p></blockquote><hr><h2 id="一、总纲" tabindex="-1">一、总纲 <a class="header-anchor" href="#一、总纲" aria-label="Permalink to &quot;一、总纲&quot;">​</a></h2><blockquote><p><strong>&quot;《心经》的核心就是讲诸法空相。整部经就是告诉我们：万事万物都是不永恒的，都是变化的。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;空不是没有，空是不永恒。你坐下时是这个你，起来时就不是完全一样的你了——细胞在变化，念头在变化。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;照见五蕴皆空——清清楚楚地明白色受想行识都是不永恒的。这就是智慧。&quot;</strong></p></blockquote><hr><h2 id="二、五蕴皆空" tabindex="-1">二、五蕴皆空 <a class="header-anchor" href="#二、五蕴皆空" aria-label="Permalink to &quot;二、五蕴皆空&quot;">​</a></h2><blockquote><p><strong>&quot;色不异空，空不异色——物质和空不是两回事。这个桌子是物质，但它由原子组成，原子里大部分是空的。色和空是一体的两面。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;受想行识，亦复如是——感受、想法、行为、意识，都和物质一样，都是变化的。没有一个永恒的&#39;我&#39;。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;你问五蕴空了没有？那你空了没有？你以为打坐空了，其实你还在，只是那些烦恼执着暂时放下了。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;色即是空，空即是色——物质本质就是空的，空也离不开物质去说。不是灭掉物质去找空，而是在物质中看到空。&quot;</strong></p></blockquote><hr><h2 id="三、诸法空相" tabindex="-1">三、诸法空相 <a class="header-anchor" href="#三、诸法空相" aria-label="Permalink to &quot;三、诸法空相&quot;">​</a></h2><blockquote><p><strong>&quot;是诸法空相，不生不灭，不垢不净，不增不减——一切法的真实相状就是不永恒。没有真的生，也没有真的灭；没有绝对的干净，也没有绝对的肮脏。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不生不灭——不是说它永远不动，而是说你看透了它的本质，发现它来来去去其实无所谓生灭，就像水变蒸气变冰，形态变了，本质没变。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;不垢不净——干净和肮脏都是人为的标准。从这个角度看是干净，从那个角度看就是肮脏。放下执着就都清净了。&quot;</strong></p></blockquote><hr><h2 id="四、度一切苦厄" tabindex="-1">四、度一切苦厄 <a class="header-anchor" href="#四、度一切苦厄" aria-label="Permalink to &quot;四、度一切苦厄&quot;">​</a></h2><blockquote><p><strong>&quot;度一切苦厄——以大智慧观照到五蕴都是不永恒的，就有办法化解一切苦厄或者绕开一切苦厄。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;心无挂碍——心里没有牵挂和障碍。挂碍是什么？是你放不下的事、放不下的人。心无挂碍了，就远离颠倒梦想。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;远离颠倒梦想，究竟涅槃——把颠倒了的人生观转过来，就究竟安宁了。颠倒是什么？把不永恒的当成永恒的，把苦的当成乐的。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;能除一切苦，真实不虚——这不是空话。你真正明白了诸法空相，很多痛苦自然就解脱了。&quot;</strong></p></blockquote><hr><h2 id="五、般若智慧" tabindex="-1">五、般若智慧 <a class="header-anchor" href="#五、般若智慧" aria-label="Permalink to &quot;五、般若智慧&quot;">​</a></h2><blockquote><p><strong>&quot;三世诸佛，依般若波罗蜜多故，得阿耨多罗三藐三菩提——过去、现在、未来所有觉悟的人，都是靠这个智慧成就的。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;般若就是智慧，波罗蜜就是到彼岸。般若波罗蜜多——用智慧到达彼岸。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;《心经》《道德经》《孝经》，这三部经通达了，其他经典就迎刃而解。《心经》的诸法空相就是《道德经》的无极。&quot;</strong></p></blockquote><blockquote><p><strong>&quot;一切圣贤，皆以无为法而有差别——三教怎么能合一？因为到了最高的境界都是一样的，只是路径不同。&quot;</strong></p></blockquote><hr><h2 id="六、简短金句" tabindex="-1">六、简短金句 <a class="header-anchor" href="#六、简短金句" aria-label="Permalink to &quot;六、简短金句&quot;">​</a></h2><blockquote><p>&quot;度一切苦厄。&quot;</p></blockquote><blockquote><p>&quot;心无挂碍。&quot;</p></blockquote><blockquote><p>&quot;远离颠倒梦想。&quot;</p></blockquote><blockquote><p>&quot;照见五蕴皆空。&quot;</p></blockquote><blockquote><p>&quot;能除一切苦，真实不虚。&quot;</p></blockquote><hr><blockquote><p>来源：<a href="/01-Raw-Sources/心经">心经</a> 整理日期：2026-05-06</p></blockquote>',39)])])}const h=t(r,[["render",a]]);export{k as __pageData,h as default};
